BASE=Path(__file__).resolve().parents[1]
OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
C=[['拉丁 campus','开阔田地、平地；操练或战斗的场地']]
CAMP=C+[['意大利 campo → 法语 camp','田地 → 军队驻扎的场地'],['英语 camp','营地；露营；引申为同一立场的阵营']]
CAMPAIGN=C+[['后期拉丁 campania → 意大利 campagna → 法语 campagne','开阔乡野；军队在野外展开的军事行动'],['英语 campaign','战役；后来用于有组织的竞选、宣传等系列行动']]
CHAMP=C+[['后期拉丁 campio / campionem → 古法语 champion','战斗者、代表别人出战的人'],['英语 champion','捍卫者；比赛冠军；动词指积极支持']]
ENCAMP=CAMP+[['英语 en- + camp → encamp','进入营地状态 → 扎营']]
DECAMP=C+[['法语 camp → décamper','营地 → 撤去营地、离开'],['英语 decamp','撤营；迅速或悄悄离开']]
CHAMPERTY=C+[['拉丁 campi pars；中世纪 campipartem → 法语 champart','田地的一份 → 分成的收获或争议财产'],['盎格鲁法语 champartie → 中古英语 champartie → champerty','资助别人的诉讼，换取诉讼所得的一部分']]
W=[
E('campaign','/kæmˈpeɪn/，亦 /kəmˈpeɪn/','战役；竞选、宣传等有组织的系列活动；参加或推动这些活动','为了一个目标连续出击：先是军队在外作战，后来是争取选票、推动改变或推广产品。','经法语 campagne 借入，接意大利 campagna、后期拉丁 campania，远源 campus。现代不能拆成 camp 营地 + 一个表示疼痛的 pain；英语动词由名词转用。',CAMPAIGN,'campaign 通常是一系列相互配合的行动。a campaign against food waste 可以包括宣传、培训和制度调整；campaign for change 中 for 说争取什么，against 说反对什么。','launch a campaign；an election campaign；campaign for better services。','event 可以只是一场活动；campaign 把一段时间内的多种行动朝同一目标组织起来。',('The town launched a campaign to reduce food waste.','镇上发起了一项减少食物浪费的行动。'),('Residents campaigned for a safer crossing near the school.','居民们持续争取在学校附近设置更安全的人行横道。'),sources=['https://www.etymonline.com/word/campaign','https://en.wiktionary.org/wiki/campaign']),
E('camp','/kæmp/','营地；露营；训练营；阵营；夸张戏剧化的风格〔来源另论〕','先看一块供人暂时驻扎的地方；再看“待在同一边的人”，就能理解支持某种主张的 camp。','现代营地义经法语 camp、意大利 campo 接 campus。古英语也曾借入同源 camp 表战斗，但不能因此把现代露营义直接画成古英语一路传下。风格义 camp 来历不明，不能认定是营地的比喻。',CAMP+[ ['另一路：camp〔夸张风格〕','二十世纪常见；更早来源不确定，不接在营地后当作确定演变'] ],'summer camp 是有组织的夏令营，未必住帐篷。the opposing camp 是另一阵营。camp style 则指有意夸张、戏剧化、常带玩味的审美；这是一条需另看的词源线。','set up camp；go camping；a training camp；the two camps。','campsite 强调供扎营的地点；camp 可以是营地、营员群体或整个营期活动。',('We made camp beside a small lake.','我们在一个小湖边扎了营。'),('The proposal divided the committee into two camps.','这项提议让委员会分成了两个阵营。'),('The costumes gave the performance a playful camp style.','这些服装让表演带上了诙谐而夸张的风格。'),sources=['https://www.etymonline.com/word/camp','https://en.wiktionary.org/wiki/camp']),
E('champion','/ˈtʃæmpiən/','冠军；积极捍卫者；大力支持、倡导','站出来替某人或某项主张出战的人，后来也指在竞赛中战胜对手的人。','古法语 champion 接后期拉丁 campio / campionem，远接 campus“战斗的场地”。更早 campio 是否经日耳曼战士词回借，资料有不同分析；稳妥的借入链从后期拉丁词起。不是现代 champ + 名词后缀 -ion。',CHAMP,'a champion of workers’ rights 是积极维护工人权益的人，未必赢过比赛。动词 champion an idea 是公开支持并推动想法实现，不是“给想法颁冠军”。','the defending champion；a champion of equality；champion a cause。','winner 是赢了某一场的人；champion 常有某项赛事、领域的冠军身份。advocate 接近倡导者义。',('She became the national chess champion.','她成为了全国国际象棋冠军。'),('The teacher championed the idea of a free school library.','这位老师积极推动建立免费学校图书馆的想法。'),sources=['https://www.etymonline.com/word/champion','https://www.merriam-webster.com/dictionary/champion','https://en.wiktionary.org/wiki/champion']),
E('championship','/ˈtʃæmpiənʃɪp/','冠军头衔；锦标赛','既可说“拥有冠军这个位置”，也可说“大家来争这个位置的比赛”。','英语 champion + -ship；-ship 表身份、状态，不是船。先有冠军身份义，后来赛事义也很常见。',CHAMP+[['英语 champion + -ship → championship','冠军身份 → 决定冠军归属的比赛']], 'win the championship 可能指赢得冠军；compete in the championships 指参加锦标赛。赛事名字常用复数 championships，不必理解成多个独立冠军身份。','a world championship；win a championship；the championship final。','champion 是冠军本人或队伍；championship 是头衔或争夺它的赛事。',('The club won its first league championship.','这家俱乐部赢得了首个联赛冠军。'),('Teams from twelve countries entered the championship.','来自十二个国家的队伍参加了这项锦标赛。'),sources=['https://www.etymonline.com/word/championship','https://en.wiktionary.org/wiki/championship']),
E('campus','/ˈkæmpəs/','校园；大学校区；集中办公园区','一片学校占用的地面，连同上面的教学楼、宿舍和活动空间，成为一个 campus。','直接借拉丁 campus“平地、田野”，英语专门发展出校园义。末尾 -us 是保留下来的拉丁词形，不是 camp 后接代词 us。',C+[['英语 campus','先用于大学占地；扩大为包括建筑的校园及集中园区']], 'on campus 在校内，live on campus 常说住学校宿舍。一个 university 可以有几个 campuses；公司也能把集中办公的园区叫 campus。','on campus；a university campus；the main campus。','university 是教育机构；campus 是它所在的实体校区，两者不总能互换。',('The library is in the centre of the campus.','图书馆位于校园中央。'),('The university opened a second campus across the river.','这所大学在河对岸开设了第二个校区。'),sources=['https://www.etymonline.com/word/campus','https://en.wiktionary.org/wiki/campus']),
E('campsite','/ˈkæmpsaɪt/','露营地；营位','给帐篷、露营车或营员落脚的一块地方，着重“在哪儿扎营”。','英语 camp + site 地点；site 不是 sight“看见”。这里是现代复合词。',CAMP+[['英语 camp + site → campsite','营地活动 + 场所 → 供露营的地方']], '在英国英语中可指有许多营位的整片露营场，在美国英语中常可指其中一个具体营位；上下文比中文译名更重要。','book a campsite；a riverside campsite；leave the campsite clean。','campground 常指整片管理的露营场；campsite 可大可小，需看地区用法。',('We booked a campsite with access to drinking water.','我们预订了一个能取到饮用水的营位。'),('Please remove all litter before leaving the campsite.','离开露营地前，请带走所有垃圾。')),
E('campaigner','英 /kæmˈpeɪnə/；美 /kæmˈpeɪnər/','活动推动者；竞选活动参与者；经验丰富的老手','不是仅仅赞成一件事，而是持续游说、组织、奔走，努力把目标推进的人。','campaign + -er；英语在已有活动名词、动词后加表人的词尾。旧式 old campaigner 还保留久经沙场的比喻。',CAMPAIGN+[['英语 campaign + -er → campaigner','参加战役或系列行动的人；倡导者、老手']], 'a campaigner for clean water 是争取洁净用水的人。a seasoned campaigner 可说很有经验的竞选者、运动员或其他老手，未必在做社会公益。','an environmental campaigner；a campaigner for reform；an old campaigner。','supporter 可能只是支持；campaigner 通常让人想到有持续实际行动。',('The campaigner collected signatures outside the station.','这位倡议者在车站外征集签名。'),('As an experienced campaigner, she stayed calm under pressure.','作为经验丰富的老手，她在压力下仍很镇定。')),
E('encampment','/ɪnˈkæmpmənt/','营地；扎营；临时聚居营区','人们搭起帐篷、设置临时住处后形成的一片落脚地，也可指这样驻扎的行为。','encamp + -ment。是英语名词构造，不必假设另有一个拉丁 encampmentum。',ENCAMP+[['英语 encamp + -ment → encampment','扎营 → 营地、扎营行为']], '常见于军队、考古、旅行或临时聚居报道，比 camp 更正式，且容易让人想到一组临时搭建的住处。','a temporary encampment；a military encampment；the remains of an encampment。','campsite 可是尚无人使用的预设地点；encampment 通常让人想到已经形成的营区。',('The survey found traces of an ancient encampment.','勘察发现了一处古代营地的痕迹。'),('The temporary encampment stood on higher ground.','这片临时营地位于较高处。'),sources=['https://www.etymonline.com/word/encamp','https://en.wiktionary.org/wiki/encampment']),
E('campo','美 /ˈkæmˌpoʊ/，亦 /ˈkɑːmˌpoʊ/','南美开阔草原、田野；乡野地区','借当地的称呼来写大片开阔乡野，常见于描写南美地貌、乡村生活的文章。','借美洲西班牙语或葡萄牙语 campo，来自拉丁 campus。另有校园口语把 campus police 缩成 campo，那是现代缩略，不能当作草原义的来源。',C+[['西班牙语／葡萄牙语 campo → 英语 campo','田野、乡间 → 南美的开阔草地或乡野']], '这个词在普通英语里远不如 field、grassland 常见。读地域游记时可抓住“当地乡野、开阔草地”，不必机械译成军营。','the open campo；life in the campo。','campus 是校园的英语借词；campo 是另一路借入的田野名称，两者都远接 campus。',('Cattle grazed across the open campo.','牛群在开阔的草原上吃草。'),('The memoir describes her childhood in the campo.','这本回忆录描写了她在乡野度过的童年。'),sources=['https://www.merriam-webster.com/dictionary/campo','https://en.wiktionary.org/wiki/campo']),
E('decamp','/diːˈkæmp/','撤营；迅速离开；悄悄溜走','把营地收起来就走，后来不必真有帐篷，也能说一群人匆匆离开或另觅落脚处。','借法语 décamper，dé- 有离开、撤除的作用，camp 接 campus。可以借助 de- + camp 理解，但整词经过法语。',DECAMP,'decamp to a hotel 是转移到酒店去住。decamp with the money 带钱跑了，语境才带不当行为；这个词本身不总表示犯罪逃跑。','decamp to somewhere；decamp with something；hastily decamp。','leave 最中性；decamp 常带突然、成群撤离或有些诙谐的口气。',('When the rain began, we decamped to a nearby café.','一下雨，我们就转移到附近一家咖啡馆。'),('The army decamped before dawn.','军队在黎明前拔营出发。'),sources=['https://www.etymonline.com/word/decamp','https://en.wiktionary.org/wiki/decamp']),
E('campesino','美 /ˌkæmpəˈsiːnoʊ/','拉丁美洲农民、农村劳动者','用西班牙语的地域称呼来谈在乡间生活和耕作的人，突出土地和乡村生计。','借西班牙语 campesino，接 campo“田野、乡间”，远源 campus；不是英语 camp 加一个表示人的 -sino。',C+[['西班牙语 campo → campesino','乡野 → 乡村居民、农民'],['英语 campesino','常用于拉丁美洲语境的农民或农业劳动者']], '复数常用 campesinos。这个词描述乡村身份或职业，不能仅凭这个称呼推定某人的族裔、土地所有权或政治立场。','campesino communities；a campesino cooperative。','farmer 是更一般的英语词；campesino 保留拉丁美洲的社会和语言背景。',('The campesinos formed a cooperative to sell their coffee.','当地农民成立合作社销售咖啡。'),('The exhibition records daily life in campesino communities.','这场展览记录了农民社区的日常生活。'),sources=['https://www.merriam-webster.com/dictionary/campesino','https://en.wiktionary.org/wiki/campesino']),
E('encamp','/ɪnˈkæmp/','扎营；使驻扎','到一个地点把临时住处安顿好，尤其容易让人想到队伍扎营。','英语 en- 使进入某种状态 + camp 营地。不是 escape“逃走”的变体。',ENCAMP,'可以不及物：the troops encamped；也可及物：encamp the soldiers，把士兵安置在营地。普通周末露营更常直接说 camp。','encamp beside a river；encamp for the night。','encamp 着重建立驻扎状态，语气较正式；decamp 是拔营离去。',('The travellers encamped beside the river for the night.','旅人们在河边扎营过夜。'),('The commander encamped the troops outside the town.','指挥官让部队在城外驻扎。'),sources=['https://www.etymonline.com/word/encamp','https://en.wiktionary.org/wiki/encamp']),
E('champignon','/ʃæmˈpɪnjən/，亦 /tʃæmˈpɪnjən/；美式亦 /ˌʃæmpiˈnjoʊn/','食用蘑菇；常指白蘑菇等','名字曾指向田野里生长的东西，英语里常在食材、菜单或菌类文字中出现。','借法语 champignon，较早 champigneul / champegnuel 追到重构的通俗拉丁 *campaniolus，接 campaneus、campania“田野”。星号表示推拟形式；不是 champion“冠军”的指小词。',C+[['后期拉丁 campania / campaneus → 重构 *campaniolus','乡野 → 田野里生长的东西'],['古法语 champegnuel / champigneul → 法语 champignon → 英语 champignon','蘑菇；英语常用于食用蘑菇，尤其白蘑菇等']], '法语里 champignon 是蘑菇的一般词，英语借用后使用范围较窄。菜单中的 champignons 常是食用菌；这不是鉴别任何野生蘑菇可否食用的依据。','sautéed champignons；champignon mushrooms。','mushroom 是普通英语词；champignon 带法语食材或专门名称的色彩。',('The chef served the pasta with sautéed champignons.','厨师给意面配上了炒蘑菇。'),('The recipe lists cultivated champignons among its ingredients.','食谱将栽培蘑菇列为原料之一。'),sources=['https://www.etymonline.com/word/champignon','https://www.merriam-webster.com/dictionary/champignon','https://en.wiktionary.org/wiki/champignon']),
E('campestral','/kæmˈpestrəl/','田野的；生长或生活在开阔乡野的','把环境画成开阔田野，而不是树林深处、城市街道或专门营地。','拉丁 campester“田野的”接 campus，英语配形容词词尾 -al；campestr- 是这条词干，不是 camp 加表示星星的 astral。',C+[['拉丁 campester → 英语 campestral','田野的 → 与开阔乡野有关的']], '这是较少见的自然史或文学词。campestral vegetation 说开阔田野的植被，不意味着它专门长在露营区。','campestral vegetation；campestral habitats。','rural 一般指乡村的；campestral 更集中于田野、开阔地的环境。',('The survey compared woodland and campestral vegetation.','这次调查比较了林地和开阔田野的植被。'),('The poem moves from crowded streets to a campestral scene.','这首诗的场景从拥挤街道转到了乡野。'),sources=['https://en.wiktionary.org/wiki/campestral','https://www.merriam-webster.com/dictionary/campestral']),
E('campimetry','/kæmˈpɪmətri/','视野测定；平面视野检查','眼睛盯住一个点，检查周围哪些位置仍能看到目标；测的是能看见的范围，不是露营地面积。','campi- 接拉丁 campus“场、范围”，-metry 接希腊“测量”词族。这里把视觉范围叫作 field，属于近代科学构词。',C+[['近代科学构件 campi- + -metry → campimetry','视野这个“场” + 测量 → 检查可见范围']], '医学里可用于视野测定，较专门的用法常指在平面屏上测试，尤其观察中央视野。不同文献对它与 perimetry 的范围划分略有区别。','tangent screen campimetry；a campimetry test。','visual acuity 测看细节有多清楚；campimetry 测视野中哪些地方能看见。',('The clinic used campimetry to map the patient’s central visual field.','诊所使用平面视野检查来绘制患者的中央视野范围。'),('During campimetry, she kept her gaze on the central target.','做视野检查时，她始终注视中央目标。'),sources=['https://www.merriam-webster.com/medical/campimetry','https://en.wiktionary.org/wiki/campimetry','https://cehjournal.org/articles/595/files/65f069bb36f81.pdf']),
E('champertous','英 /ˈtʃæmpətəs/；美 /ˈtʃæmpərtəs/','构成或涉及帮人打官司以分取所得的〔法律〕','说一种安排带有“我资助你打官司，赢了分我一份”的性质。','英语 champerty 去词尾 -y，加 -ous；这次是现代派生，不要把每个词都说成独立拉丁借入。',CHAMPERTY+[['英语 champerty + -ous → champertous','与诉讼资助分成有关的']], '常修饰 agreement、arrangement。具体安排是否在某个法域被如此认定、有什么后果，需要看法律和事实；词本身不能替代判断。','a champertous agreement；a champertous arrangement。','champerty 是这类安排的名词；champertous 是描述安排性质的形容词。',('The judge examined whether the agreement was champertous.','法官审查了这份协议是否构成诉讼资助分成安排。'),('The article discusses the history of champertous contracts.','这篇文章讨论了此类诉讼分成合同的历史。'),sources=['https://www.merriam-webster.com/dictionary/champerty','https://www.etymonline.com/word/champerty','https://www.law.cornell.edu/wex/champerty']),
E('champerty','英 /ˈtʃæmpəti/；美 /ˈtʃæmpərti/','助讼取酬；以分取诉讼所得为条件资助他人诉讼的安排','早期“从田地收成分一份”的画面，转到争议财产：外部资助者帮忙打官司，条件是成功后分到一部分。','经盎格鲁法语 champartie 借入；champart 可追到田地收成分成，常联系拉丁 campi pars“田地的一份”。campi 在这个短语里是属格“田地的”，不是把一群营地合起来。',CHAMPERTY,'它是有特定历史和法律背景的概念，不能把任何法律援助或现代诉讼融资一概等同于它。常见讨论关注外部资助、本人原本的利害关系和分享诉讼成果等条件。','the doctrine of champerty；champerty and maintenance。','maintenance 在这组法律用法里泛指外部助讼；champerty 还着重期待分享胜诉所得。',('The seminar traced the doctrine of champerty through old court cases.','研讨会通过旧判例追溯了助讼取酬这一法律概念。'),('The lawyer distinguished ordinary legal aid from champerty.','律师区分了普通法律援助和以分取诉讼所得为条件的助讼安排。'),sources=['https://www.etymonline.com/word/champerty','https://www.merriam-webster.com/dictionary/champerty','https://www.law.cornell.edu/wex/champerty']),
E('decampment','/diːˈkæmpmənt/','撤营；匆忙离开','把“收拾东西走人”这次行动当成一件事来讲，语气比 departure 更特别。','decamp + -ment，在英语动词后加行为名词词尾；不是与 encampment 相同的“营地”名称。',DECAMP+[['英语 decamp + -ment → decampment','撤营、离开这个动作']], '较少见，常出现在历史叙述或带幽默、批评意味的文体里。一般旅行离开说 departure 更自然。','a sudden decampment；the decampment of the troops。','encampment 常是营地或扎营；decampment 是离开、撤走，方向相反。',('The diary records the troops’ decampment at first light.','日记记载了部队在天刚亮时拔营。'),('Their sudden decampment left the house strangely quiet.','他们突然离开后，房子安静得有些异样。')),
]
ROOT=dict(id='C0163',meaning='田野、开阔平地；活动或驻扎的场地',core='一块开阔地，可以用来驻扎、打仗、比赛，也可以成为校园或耕地。记住场地这幅画面，再看各词在哪个场景发展。',image='同一片开阔地上，军队扎营、战士出战、农人耕作；后来词义各自发展，不能把现代所有词都硬译成露营。',intro='拉丁 campus 表田野、平地、操练场。法语后代可写 champ-，意大利语写 campo；英语有经法语借入的 camp、champion，也直接借了 campus。更早来源并不确定，本页从有记录的拉丁词开始。',forms='camp- 常保留在 camp、campus；champ- 是法语发展出的形态，如 champion、champignon；campi- 在 campimetry 中作科学构件。campaign 经 campania、campagna、campagne 借入，不是 camp 与 pain 的拼合。',branches=[['驻扎和撤离','camp, campsite, encamp, encampment, decamp, decampment'],['出战、争取目标','campaign, campaigner, champion, championship'],['校园与田野','campus, campo, campesino, campestral, champignon'],['视野与法律专词','campimetry, champerty, champertous']],contrasts='camp 的夸张审美义来源不明，不认作田野义的确定后代。champion 是代表人出战、争冠或捍卫者，不是现代 camp 的营员。champerty 的 part 指分得的一份；campimetry 测的是视野。',practice='用同一场景分清动作：We encamped near the campus, stayed at the campsite for two nights, and then decamped. 我们在校园附近扎营，在营地住了两夜，然后离开。campaign 则讲有组织地争取目标，不必真的扎营。',words=[],exclude={})
